  (* [comment removed for export] *)
  Lemma hC_dec : forall (ra t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (r : Z) (m1 : fmem) (jd : list byte),
    0 <= r < 2^64 -> (r < 2^64 - 119 -> dt_ok m1 DT mtl) ->
    bytes_at psegs m1 D (map (Z_to_bv 8) pl) ->
    rw_cells psegs m1 DST [CB (Z.to_nat dbs) jd] ->
    munch WC m0 m1 -> wmono psegs m0 m1 -> mem_inv psegs m1 -> stk psegs m1 lo SP ->
    evt psegs hC_post
      (MS (mkR ra (Z_to_bv 64 SP) gp tp t0 t1 t2 (Z_to_bv 64 P) (Z_to_bv 64 D) (Z_to_bv 64 r)
               a1 a2 a3 a4 a5 a6 a7 (Z_to_bv 64 streams) (Z_to_bv 64 symbols) (Z_to_bv 64 flags) (Z_to_bv 64 DT)
               (Z_to_bv 64 dbs) (Z_to_bv 64 W) (Z_to_bv 64 DST) (Z_to_bv 64 rest) (Z_to_bv 64 8704) s11 t3 t4 t5 t6)
